// Checkout handler with paidEvent logging
const { logPaidEvent } = require('./revenueTracker');

async function handleCheckout(req, res) {
  try {
    const { userId, plan, amount, currency } = req.body;
    // Process payment (simplified)
    const paymentSuccess = await processPayment(userId, amount, currency);
    if (paymentSuccess) {
      await logPaidEvent({ userId, plan, amount, currency, timestamp: new Date().toISOString() });
      res.status(200).json({ status: 'success', paidEvent: true });
    } else {
      res.status(402).json({ status: 'failed', paidEvent: false });
    }
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ status: 'error', message: err.message });
  }
}

